// ✅ Reads correctly from body where n8n puts it
const body = $json.body;

const location = String(body.location || '').trim();
const maxDistance = Number(body.max_distance_km || 5);

if (!location) {
  throw new Error('Please provide a location.');
}

return [{
  json: {
    location,
    max_distance_km: Number.isFinite(maxDistance) && maxDistance > 0
      ? maxDistance
      : 5
  }
}];

const items = $json.items || [];
if (!items.length) return [];

const latest = items[items.length - 1];
const carparkData = latest.carpark_data || [];
const results = [];

for (const cp of carparkData) {
  const carpark_number = cp.carpark_number;
  const infoList = cp.carpark_info || [];

  let total_all = 0;
  let avail_all = 0;
  let hasCarLots = false;

  for (const info of infoList) {
    const total = Number(info.total_lots) || 0;
    const avail = Number(info.lots_available) || 0;
    if (info.lot_type === 'C') hasCarLots = true;
    total_all += total;
    avail_all += avail;
  }

  if (!hasCarLots || total_all <= 0) continue;

  results.push({
    carpark_number: carpark_number,
    total_lots: total_all,
    lots_available: avail_all,
    availability_pct: Math.round((avail_all / total_all) * 100)
  });
}

return results;

const records = $json.result?.records || [];
const results = [];

for (const r of records) {
  const easting = Number(r.x_coord);
  const northing = Number(r.y_coord);

  if (!Number.isFinite(easting) || !Number.isFinite(northing)) {
    continue;
  }

  results.push({
    carpark_number: String(r.car_park_no || ''),
    address: String(r.address || ''),
    easting,
    northing,
    car_park_type: String(r.car_park_type || ''),
    type_of_parking_system: String(r.type_of_parking_system || ''),
  });
}

return results;

// ============================================================
// HDB CARPARK FINDER — Smart & Accurate Location Search
// ============================================================

// ─── STEP 1: Get user input ─────────────────────────────────
const searchInput = $node["Prepare Request"].json.location;
const maxDistKm = $node["Prepare Request"].json.max_distance_km || 5;

console.log("=".repeat(60));
console.log("🔍 Searching for:", searchInput);
console.log("📏 Radius:", maxDistKm, "km");
console.log("=".repeat(60));

// ─── STEP 2: Auto-detect Postal Code ────────────────────────
const postalMatch = searchInput.match(/\b(\d{6})\b/);
let searchQuery = searchInput;

if (postalMatch) {
  searchQuery = postalMatch[1];
  console.log("📮 Postal code detected → using exact location:", searchQuery);
} else {
  console.log("🏷️  Using name search:", searchQuery);
}

// ─── STEP 3: Get OneMap results ─────────────────────────────
const allResults = $node["OneMap Geocode"].json.results || [];

if (!allResults.length) {
  throw new Error(`❌ No location found for: ${searchInput}\nTry adding a postal code.`);
}

console.log(`📍 Found ${allResults.length} match(es) — selecting best...`);

// ─── STEP 4: Pick best location match ────────────────────────
let bestMatch = null;
let highestScore = -1;
const searchLower = searchQuery.toLowerCase();

for (const result of allResults) {
  const buildingName = (result.BUILDINGNAME || "").toLowerCase();
  const displayName = (result.SEARCHVAL || "").toLowerCase();
  const roadName = (result.ROAD || "").toLowerCase();
  const fullAddress = (result.ADDRESS || "").toLowerCase();

  let score = 0;
  if (buildingName === searchLower || displayName === searchLower) score = 100;
  else if (buildingName.includes(searchLower) || displayName.includes(searchLower)) score = 80;
  else if (fullAddress.includes(searchLower)) score = 60;
  else if (roadName.includes(searchLower)) score = 40;

  if (result.BUILDINGNAME && result.BUILDINGNAME !== "NIL") score += 15;
  if (result.SUBZONE && result.SUBZONE !== "NIL") score += 8;

  if (score > highestScore) {
    highestScore = score;
    bestMatch = result;
  }
}

if (!bestMatch) {
  bestMatch = allResults[0];
  console.log("⚠️  Using first result as fallback");
}

// ─── STEP 5: Center coordinates ─────────────────────────────
const centerLat = Number(bestMatch.LATITUDE || bestMatch.lat || 0);
const centerLng = Number(bestMatch.LONGITUDE || bestMatch.lng || 0);
const displayName = bestMatch.BUILDINGNAME || bestMatch.SEARCHVAL || bestMatch.ADDRESS;

console.log("✅ SELECTED:", displayName);
console.log("📍 Coords :", centerLat.toFixed(6), ",", centerLng.toFixed(6));
console.log("⭐ Match  :", highestScore, "/ 100");

// ─── STEP 6: SVY21 → Lat/Lng converter ──────────────────────
function svy21ToLatLng(easting, northing) {
  if (!easting || !northing) return null;
  const originE = 28001.642;
  const originN = 38744.572;
  const originLat = 1.366666;
  const originLng = 103.833333;
  const dN = northing - originN;
  const dE = easting - originE;
  const lat = originLat + (dN / 111320);
  const lng = originLng + (dE / 111320) / Math.cos(originLat * Math.PI / 180);
  return { lat, lng };
}

// ─── STEP 7: Distance calculator ────────────────────────────
function getDistanceKm(lat1, lng1, lat2, lng2) {
  if (!lat1 || !lng1 || !lat2 || !lng2) return 999;
  const toRad = deg => deg * Math.PI / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 +
            Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
            Math.sin(dLng / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// ─── STEP 8: Process all carparks ───────────────────────────
const allCarparks = $input.all();
const results = [];

console.log("📥 Total matched carparks from Merge:", allCarparks.length);

for (const item of allCarparks) {
  const cp = item.json;

  const coords = svy21ToLatLng(Number(cp.easting), Number(cp.northing));
  if (!coords) continue;

  const distance = getDistanceKm(centerLat, centerLng, coords.lat, coords.lng);
  const softLimit = maxDistKm * 1.15;
  if (distance > softLimit) continue;

  const avail = Number(cp.lots_available) || 0;
  const total = Number(cp.total_lots) || 0;
  if (total <= 0) continue;

  const availPct = Math.round((avail / total) * 100 * 10) / 10;

  results.push({
    car_park_no: cp.carpark_number,
    carpark_number: cp.carpark_number,
    address: cp.address || "Address unavailable",
    lat: coords.lat,
    lon: coords.lng,
    distance_km: Math.round(distance * 100) / 100,
    total_lots: total,
    lots_available: avail,
    availability_pct: availPct,
    car_park_type: cp.car_park_type || "",
    type_of_parking_system: cp.type_of_parking_system || ""
  });
}

// ─── STEP 9: Sort & return ──────────────────────────────────
console.log("✅ Final results within range:", results.length);
console.log("=".repeat(60));

return [{
  json: {
    destination: displayName,
    search_radius_km: maxDistKm,
    search_score: highestScore,
    center: { lat: centerLat, lng: centerLng },
    candidates_found: results.length,
    carparks: results
  }
}];
